CREATE TABLE question_papers(id uuid PRIMARY KEY,teacher_id uuid NOT NULL REFERENCES teachers(id),title text NOT NULL,subject text NOT NULL,total_marks integer NOT NULL CHECK(total_marks>0),duration_seconds integer NOT NULL CHECK(duration_seconds BETWEEN 60 AND 86400),pdf bytea NOT NULL,sha256 text NOT NULL,page_count integer NOT NULL,byte_count integer NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz);
CREATE TABLE session_papers(session_id uuid PRIMARY KEY REFERENCES sessions(id),paper_id uuid NOT NULL REFERENCES question_papers(id),teacher_id uuid NOT NULL REFERENCES teachers(id),opens_at timestamptz NOT NULL,closes_at timestamptz NOT NULL,all_devices boolean NOT NULL DEFAULT true,assigned_at timestamptz NOT NULL DEFAULT now(),CHECK(closes_at>opens_at));
CREATE TABLE paper_assignment_devices(session_id uuid NOT NULL REFERENCES session_papers(session_id),device_id uuid NOT NULL REFERENCES devices(id),PRIMARY KEY(session_id,device_id));
CREATE TABLE exam_attempts(id uuid PRIMARY KEY,session_id uuid NOT NULL REFERENCES session_papers(session_id),device_id uuid NOT NULL REFERENCES devices(id),status text NOT NULL CHECK(status IN ('opened','started','submitted','cancelled')),opened_at timestamptz NOT NULL DEFAULT now(),started_at timestamptz,deadline_at timestamptz,submitted_at timestamptz,submission_reason text,answers text NOT NULL DEFAULT '',UNIQUE(session_id,device_id));
CREATE TABLE student_launches(code_hash text PRIMARY KEY,device_id uuid NOT NULL REFERENCES devices(id),session_id uuid NOT NULL REFERENCES session_papers(session_id),expires_at timestamptz NOT NULL);
CREATE TABLE paper_audit(id uuid PRIMARY KEY,teacher_id uuid NOT NULL REFERENCES teachers(id),paper_id uuid REFERENCES question_papers(id),session_id uuid REFERENCES sessions(id),device_id uuid REFERENCES devices(id),action text NOT NULL,detail jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX paper_audit_teacher_time ON paper_audit(teacher_id,created_at);
CREATE INDEX exam_attempts_session ON exam_attempts(session_id,status);
